// 1. One phone format for everyone
const normPhone = p => {
  const d = String(p ?? '').replace(/\D/g, '');       // keep digits only
  if (!d) return null;
  if (d.startsWith('234')) return '+' + d;
  if (d.startsWith('0')) return '+234' + d.slice(1);
  return '+234' + d;
};

// 2. Group orders by phone
const byPhone = {};
for (const item of $input.all()) {
  const o = item.json;
  const phone = normPhone(o.phone);
  if (!phone) continue;                               // no phone: handled by an IF before this node
  const c = byPhone[phone] ??= {
    phone, name: String(o.name).trim(), orders: 0,
    lifetime_value: 0, first_order: o.date, last_order: o.date,
  };
  c.orders += 1;
  c.lifetime_value += Number(o.total) || 0;           // "45000" → 45000
  if (o.date < c.first_order) c.first_order = o.date;
  if (o.date > c.last_order) { c.last_order = o.date; c.name = String(o.name).trim(); }
}

// 3. Rank by value and return items
return Object.values(byPhone)
  .sort((a, b) => b.lifetime_value - a.lifetime_value)
  .map((c, i) => ({ json: { ...c, rank: i + 1 } }));

