// Exact arithmetic for the agent. Input: an expression such as 3*12500 + 2*9000
const src = String(query).replace(/[,₦\s]/g, '');
if (!/^[0-9+\-*/().]+$/.test(src)) return 'Error: use only numbers and + - * / ( )';
let i = 0;
const num = () => { const m = src.slice(i).match(/^\d+(\.\d+)?/); if (!m) throw new Error('bad number'); i += m[0].length; return Number(m[0]); };
const factor = () => {
  if (src[i] === '-') { i++; return -factor(); }
  if (src[i] === '(') { i++; const v = expr(); if (src[i] !== ')') throw new Error('missing )'); i++; return v; }
  return num();
};
const term = () => { let v = factor(); while (src[i] === '*' || src[i] === '/') { const op = src[i++]; const r = factor(); v = op === '*' ? v * r : v / r; } return v; };
const expr = () => { let v = term(); while (src[i] === '+' || src[i] === '-') { const op = src[i++]; const r = term(); v = op === '+' ? v + r : v - r; } return v; };
try { const v = expr(); if (i !== src.length) throw new Error('unexpected ' + src[i]); return String(Math.round(v * 100) / 100); }
catch (e) { return 'Error: ' + e.message; }

// Long-term memory: this customer's newest order, from the Orders sheet.
const chatId = String($('When Executed by Another Workflow').first().json.chat_id ?? '');
const rows = $input.all().map(i => i.json)
  .filter(r => r.order_id && String(r.chat_id) === chatId)
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
if (!chatId || !rows.length) return [{ json: { found: false } }];
const o = rows[0];
let items;
try { items = JSON.parse(o.items_json).map(l => ({ product: l.name, qty: l.qty, unit: l.unit })); }
catch (e) { items = o.items_json; }
return [{ json: { found: true, order_id: o.order_id, items, date: o.delivery_date || o.created_at } }];

// Identity comes from the channel: only this chat's orders are ever visible.
const t = $('When Executed by Another Workflow').first().json;
const chatId = String(t.chat_id ?? '');
const wanted = String(t.order_id ?? '').toUpperCase().trim();
const mine = $input.all().map(i => i.json)
  .filter(r => r.order_id && String(r.chat_id) === chatId)
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
const tidy = o => {
  let items;
  try { items = JSON.parse(o.items_json).map(l => ({ product: l.name, qty: l.qty, unit: l.unit })); } catch (e) { items = o.items_json; }
  return { order_id: o.order_id, items, total: Number(o.total), status: o.status, delivery_date: o.delivery_date,
           rider: o.rider || undefined, refunded: o.refunded || 'no' };
};
if (!chatId) return [{ json: { found: false, error: 'No customer identity' } }];
if (wanted) {
  const o = mine.find(r => String(r.order_id).toUpperCase() === wanted);
  // Same answer whether the order doesn't exist or belongs to someone else: nothing leaks.
  if (!o) return [{ json: { found: false, message: `No order ${wanted} on this customer's account.` } }];
  return [{ json: { found: true, ...tidy(o) } }];
}
if (!mine.length) return [{ json: { found: false, message: 'This customer has no orders yet.' } }];
return [{ json: { found: true, orders: mine.slice(0, 3).map(tidy) } }];

// Hard limits: code decides, not the model.
const t = $('When Executed by Another Workflow').first().json;
const chat_id = String(t.chat_id ?? '');
const order_id = String(t.order_id ?? '').toUpperCase().trim();
const amount = Number(t.amount);
const reason = String(t.reason ?? '');
const order = $input.all().map(i => i.json).find(r => String(r.order_id).toUpperCase() === order_id);
let stop = null;
if (!order)                                     stop = "Order not found";
else if (!chat_id)                              stop = "No customer identity";
else if (String(order.chat_id) !== chat_id)     stop = "Order doesn't belong to this customer";
else if (order.status !== 'Paid')               stop = "Order not paid";
else if (order.refunded === 'yes')              stop = "Already refunded";
else if (!(amount > 0) || amount > Number(order.total)) stop = "Amount outside the order total";
else if (amount > 50000)                        stop = "Over ₦50,000: Tolu handles by phone";
return [{ json: { ok: !stop, stop, order_id, chat_id, amount, reason,
  total: order ? Number(order.total) : null, status: order ? order.status : null,
  paystack_ref: order ? order.paystack_ref : null, is_eval: String(t.is_eval) === 'true' } }];

