// This week vs last week, one small row per product, with its source.
const rows = $input.all().map(i => i.json).filter(r => r.name && r.price !== '' && r.price_last_week !== '');
const items = rows.map(r => ({
  product: r.name,
  price_now: Number(r.price),
  price_last_week: Number(r.price_last_week),
  source: `Agro Depot price list, ${String(r.fetched_at || '').slice(0, 10)}`,
}));
return [{ json: { found: items.length > 0, items } }];

// Top sellers over the last 7 days, from Orders.
const since = $now.setZone('Africa/Lagos').minus({ days: 7 }).toISO();
const qty = {};
for (const o of $input.all().map(i => i.json)) {
  if (!o.created_at || String(o.created_at) < since) continue;
  let lines = [];
  try { lines = JSON.parse(o.items_json); } catch (e) { continue; }
  for (const l of lines) qty[l.name] = (qty[l.name] || 0) + Number(l.qty || 0);
}
const top = Object.entries(qty).sort((a, b) => b[1] - a[1]).slice(0, 5)
  .map(([product, units]) => ({ product, units_sold: units, source: 'Harvest Lane Orders, last 7 days' }));
return [{ json: { top_sellers: top } }];

// Facts must be right before anyone writes. Code checks the hand-off.
const r = $json.output ?? $json;
const problems = [];
const items = Array.isArray(r.items) ? r.items : [];
if (!items.length) problems.push('No items in research');
for (const it of items) {
  for (const k of ['price_now', 'price_last_week']) {
    if (typeof it[k] !== 'number' || !(it[k] > 0)) problems.push(`${it.product ?? '?'}: missing ${k}`);
  }
  if (!it.source) problems.push(`${it.product ?? '?'}: missing source`);
  // Recalculate change_pct in code and overwrite whatever the model wrote.
  if (it.price_last_week > 0) it.change_pct = Math.round((it.price_now - it.price_last_week) / it.price_last_week * 1000) / 10;
}
return [{ json: { ok: problems.length === 0, problems, research: { week: r.week, items, notes: r.notes ?? [] } } }];

