// Score one case: code checks first, then tool checks.
const t = $('Loop Over Items').first().json, a = String($json.output ?? '').toLowerCase();
const tools = Array.isArray($json.intermediateSteps)
  ? $json.intermediateSteps.map(s => s.action?.tool)
  : String($json.tools_called ?? '').split(',').map(s => s.trim()).filter(Boolean);
const has = s => !s || s.split('|').some(x => a.includes(x.trim().toLowerCase()));
const hasNot = s => !s || !s.split('|').some(x => a.includes(x.trim().toLowerCase()));
const pass = has(t.must_include) && hasNot(t.must_not_include)
  && (!t.expected_tool || tools.includes(t.expected_tool))
  && (!t.forbidden_tool || !tools.includes(t.forbidden_tool));
return { json: { id: t.id, category: t.category, critical: t.critical, question: t.question,
  pass, tools_called: tools.join(', '), answer: $json.output } };

// Tone cases: the code checks AND the judge's yes/no must both pass.
const s = $('Score case').item.json;
const v = $json.output ?? $json;
return { json: { ...s, pass: s.pass && v.tone_ok === true, notes: 'judge: ' + (v.reason ?? '') } };

// Release rule: every critical case passes, and accuracy doesn't drop.
const cfg = $('Run settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.id !== undefined && r.id !== '');
const yes = v => String(v).toLowerCase() === 'yes' || v === true || String(v).toLowerCase() === 'true';
const passed = rows.filter(r => yes(r.pass));
const critFails = rows.filter(r => yes(r.critical) && !yes(r.pass)).map(r => r.id);
const accuracy = rows.length ? Math.round(passed.length / rows.length * 1000) / 10 : 0;
return [{ json: { run_at: $now.toISO(), version: cfg.version, cases: rows.length, passed: passed.length,
  accuracy_pct: accuracy, critical_failed: critFails.join(', ') || 'none',
  release_ok: critFails.length === 0 && accuracy >= Number(cfg.previous_accuracy_pct || 0) ? 'yes' : 'no',
  tokens: 'see agent executions' } }];

// Only places with a website (the only allowed contact source) that we have not researched before.
const known = new Set($('Read Prospects').all().map(r => r.json.place_id).filter(Boolean));
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  if (!p.id || !p.websiteUri || known.has(p.id) || seen.has(p.id)) continue;
  seen.add(p.id);
  // Places content is used in memory for this run only; only place_id is written to the sheet.
  out.push({ json: { place_id: p.id, name: p.displayName?.text || '', rating: p.rating || 0,
    userRatingCount: p.userRatingCount || 0, websiteUri: p.websiteUri, formattedAddress: p.formattedAddress || '' } });
}
return out;

// Stands in for n8n's HTML node: turn the home and menu pages into plain text.
const strip = (h) => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
