const out = [];
for (const item of $input.all()) {
  const { brief, versions } = item.json;
  for (const v of versions) {
    out.push({ json: {
      post_key: `${brief.calendar_id}-${v.platform}`, calendar_id: brief.calendar_id, platform: v.platform,
