const now = new Date();
const budget = $('Settings').first().json.x_monthly_budget_usd;
const posts = $('Read Posts').all().map(i => i.json);
const prices = $('Read Price list').all().map(i => i.json);
const month = now.toISOString().slice(0, 7);
const xCost = (p) => /https?:\/\//.test(p.caption) ? 0.20 : 0.015;   // check X's current pricing
let xSpent = posts.filter(p => p.platform === 'x' && String(p.published_at).startsWith(month)).reduce((a, p) => a + xCost(p), 0);
const out = [];
for (const p of posts) {
  if (p.status !== 'approved' || p.post_id || new Date(p.scheduled_at) > now) continue;
  let hold = '';
  if (String(p.uses_price) === 'true') {
    const cur = prices.find(r => String(r.product).toLowerCase() === String(p.product).toLowerCase());
    if (!cur || String(cur.price).replace(/[^\d]/g, '') !== String(p.price_used).replace(/[^\d]/g, '')) hold = `price changed (approved ₦${p.price_used}, now ₦${cur ? cur.price : 'missing'})`;
  }
  if (!hold && p.platform === 'x') {
    if (xSpent + xCost(p) > budget) hold = `X monthly budget ($${budget}) reached`;
    else xSpent += xCost(p);
  }
  out.push({ json: { ...p, route: hold ? 'hold' : 'publish', hold_reason: hold } });
}
return out;

