const m = $('Allowed actions').item.json;
const a = m.allowed;
const o = $json.output || {};
const meta = ['facebook', 'instagram'].includes(m.platform);
const assisted = ['linkedin', 'tiktok'].includes(m.platform);
const needs = { public_reply: ['public'], private_reply: ['private'], public_and_private: ['public', 'private'], dm: ['dm'], hide: ['public'], handover: [] };
let action = o.action, reason = '';
if (!(action in needs)) { action = 'handover'; reason = 'unknown action'; }
else if (needs[action].some(k => !a[k])) { reason = `${action} is not allowed here`; action = 'handover'; }
if (action === 'hide' && !meta) { action = 'handover'; reason = 'hide is only for Facebook and Instagram comments'; }
if (m.platform === 'x' && ['private_reply', 'public_and_private', 'dm'].includes(action)) { action = 'handover'; reason = 'X: public replies only in this build'; }
// Personal details never go in public.
const personal = /(\+?234|\b0)[789]\d{9}|[\w.+-]+@[\w-]+\.\w+|\bHL-\d+|\d+\s+\w+\s+(road|rd|street|st|close|avenue|ave|crescent)\b/i;
if (['public_reply', 'public_and_private'].includes(action) && personal.test(o.public_text || '')) { action = 'handover'; reason = 'personal details in a public reply'; }
let route = 'auto';
if (action === 'handover' || assisted) route = 'tolu';
else if (!a.auto) route = 'approve';
return { ...m, action, public_text: o.public_text || '', private_text: o.private_text || '', lead: !!o.lead, reject_reason: reason, route };

