// The signature is computed over the exact raw bytes Meta sent, not over re-serialised JSON.
const item = $input.first();
let raw;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) {
  raw = JSON.stringify(item.json.body); // fallback only; turn on Raw Body in the webhook options
}
return [{ json: { raw, signature: item.json.headers['x-hub-signature-256'] || '' } }];

// One row per comment or message: platform, kind, item_id, thread_id, author_handle, text, received_at, last_customer_msg_at
const body = JSON.parse($('Signature valid?').first().json.raw);
const now = new Date().toISOString();
const platform = body.object === 'instagram' ? 'instagram' : 'facebook';
const out = [];
for (const entry of body.entry || []) {
  for (const ch of entry.changes || []) {
    const v = ch.value || {};
    if (v.from && v.from.id === entry.id) continue; // our own replies
    if (platform === 'facebook' && ch.field === 'feed' && v.item === 'comment' && v.verb === 'add') {
      out.push({ platform, kind: 'comment', item_id: v.comment_id, thread_id: v.post_id, author_handle: v.from?.name || '',
        text: v.message || '', source_link: v.post?.permalink_url || '',
        received_at: v.created_time ? new Date(v.created_time * 1000).toISOString() : now });
    }
    if (platform === 'instagram' && ch.field === 'comments') {
      out.push({ platform, kind: 'comment', item_id: v.id, thread_id: v.media?.id || '', author_handle: v.from?.username || '',
        text: v.text || '', source_link: '', received_at: now });
    }
  }
  for (const m of entry.messaging || []) {
    if (!m.message || m.message.is_echo) continue;
    out.push({ platform, kind: 'dm', item_id: m.message.mid, thread_id: m.sender.id, author_handle: m.sender.id,
      text: m.message.text || '', source_link: '', received_at: new Date(m.timestamp).toISOString() });
  }
}
return out.map(e => ({ json: { ...e, last_customer_msg_at: e.received_at } }));

