const problems = [];
for (const a of text.match(/₦\s?[\d,]+/g) || []) {
  const n = a.replace(/[^\d]/g, '');
  if (!allowedAmounts.has(n) && !offersText.includes(n)) problems.push(`price ${a} is not in the price list`);
}
for (const p of text.match(/\d+\s?%/g) || []) if (!offersText.includes(p.replace(/\s/g, ''))) problems.push(`discount ${p} is not an approved offer`);
if (/\b(discount|% off|buy one get one|free delivery)\b/i.test(text) && !f.offers.length) problems.push('mentions an offer but no offer is approved');
return [{ json: { ...o, problems, passes: problems.length === 0 } }];

