parameters.jsCode:
const SOURCES = { instagram: 'Instagram', ig: 'Instagram', insta: 'Instagram', 'instagram ad': 'Instagram', facebook: 'Facebook', fb: 'Facebook',
  whatsapp: 'WhatsApp', outreach: 'Outreach', email: 'Outreach', referral: 'Referral', website: 'Website', event: 'Event' };
const TYPES = ['restaurant', 'hotel', 'caterer', 'household'];
const STAGES = { 'new enquiry': 'New enquiry', 'tasting booked': 'Tasting booked', 'proposal sent': 'Proposal sent', 'trial order': 'Trial order', won: 'Won', lost: 'Lost' };
const OWNERS = ['Tolu', 'Bisi'];
const phoneFix = (p) => { const d = String(p || '').replace(/\D/g, '').replace(/^(234|0)/, ''); return d.length === 10 ? '+234' + d : ''; };
const domainFix = (w) => String(w || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
const out = [], problems = [];
const seenEmail = new Set(), companies = new Map();
let people = 0;
for (const { json: r } of $input.all()) {
  const row = r.row_number;
  const role = String(r.role || '').toLowerCase();
  const email = String(r.email || '').trim().toLowerCase();
  if (['staff', 'supplier', 'test'].includes(role) || /test|example\.com$/.test(email)) { problems.push({ row, problem: `removed: ${role || 'test row'}` }); continue; }
  if (email && seenEmail.has(email)) { problems.push({ row, problem: `duplicate email ${email}` }); continue; }
  if (email) seenEmail.add(email);
  const source = SOURCES[String(r.lead_source || '').trim().toLowerCase()];
  if (!source) problems.push({ row, problem: `lead_source "${r.lead_source}" is not a dropdown value` });
  const type = String(r.business_type || '').trim().toLowerCase();
  if (!TYPES.includes(type)) problems.push({ row, problem: `business_type "${r.business_type}" is not a dropdown value` });
  let consent = String(r.marketing_consent || '').trim().toLowerCase();
  if (!['yes', 'no'].includes(consent)) consent = 'unknown';
  if (consent === 'yes' && !r.consent_date) { consent = 'unknown'; problems.push({ row, problem: 'consent yes without a date: set to unknown (a WhatsApp contact is not email consent)' }); }
  const domain = domainFix(r.website);
  if (r.company && !domain) problems.push({ row, problem: `company "${r.company}" has no domain` });
  const batch = people < 10 ? 'batch 1 (first 10)' : 'batch 2';
  people++;
  if (domain && !companies.has(domain)) {
    companies.set(domain, true);
    out.push({ record_type: 'company', batch, name: r.company, domain, business_type: TYPES.includes(type) ? type : '', delivery_zone: String(r.delivery_zone || '').toLowerCase() === 'in' ? 'in' : 'out' });
  }
  out.push({ record_type: 'contact', batch, firstname: String(r.name || '').split(' ')[0], lastname: String(r.name || '').split(' ').slice(1).join(' '),
    email, phone: phoneFix(r.phone), company_domain: domain, lead_source: source || '', marketing_consent: consent, consent_date: consent === 'yes' ? r.consent_date : '' });
  const stage = STAGES[String(r.deal_stage || '').trim().toLowerCase()];
  if (r.deal_stage && !stage) problems.push({ row, problem: `deal_stage "${r.deal_stage}" is not one of the 5 stages` });
  if (stage) {
    const open = !['Won', 'Lost'].includes(stage);
    if (open && !OWNERS.includes(r.owner)) problems.push({ row, problem: 'open deal without an owner (Tolu or Bisi)' });
    if (open && !r.next_step_date) problems.push({ row, problem: 'open deal without a next step date' });
    if (stage === 'Lost' && !r.lost_reason) problems.push({ row, problem: 'lost deal without a lost reason' });
    out.push({ record_type: 'deal', batch, dealname: `${r.company || r.name} · weekly supply`, dealstage: stage, weekly_value_ngn: Number(String(r.weekly_value_ngn || '').replace(/[^\d]/g, '')) || '',
      hubspot_owner: r.owner || '', next_step_date: r.next_step_date || '', lost_reason: r.lost_reason || '', company_domain: domain, contact_email: email });
  }
}
return [...out, ...problems.map(p => ({ record_type: 'problem', ...p }))].map(j => ({ json: j }));

const d = String($json.phone || '').replace(/\D/g, '').replace(/^(234|0)/, '');
return { ...$json,
  email: String($json.email || '').trim().toLowerCase(),
  phone: d ? '+234' + d : '',
  domain: String($json.domain || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0] };

const ids = $('Contact ID').item.json;
let deal_id = '';
try { deal_id = $('Deal: create at New enquiry').item.json.id || ''; } catch (e) {}
if (!deal_id) { try { deal_id = $('Open deals for this company').item.json.results?.[0]?.id || ''; } catch (e) {} }
return { ...$('1 Normalise').item.json, contact_id: ids.contact_id, company_id: ids.company_id, deal_id, lifecyclestage: ids.lifecyclestage };

// Code node: weights calibrated in the Card 3 lab against last quarter
const W = { type: 20, asked: 25, opens: 5, size: 10 };
const L = $json;
if (L.delivery_zone !== 'in')
  return { ...L, harvest_score: 0, ready: false, why: 'outside delivery zone' };
let s = 30; // in zone
if (['restaurant','hotel','caterer'].includes(L.business_type)) s += W.type;
if (L.asked_price_or_tasting) s += W.asked;
if (L.email_opens >= 3) s += W.opens;
if (L.staff >= 20) s += W.size;
return { ...L, harvest_score: s, ready: s >= 65 };

// Loop guard: react only to the field we need, and ignore changes made by integrations (including ours).
return $input.all().filter(i => i.json.propertyName === 'dealstage'
  && !['INTEGRATION', 'API'].includes(String(i.json.changeSource || '').toUpperCase()));

const call = $('Call first').first().json.results || [];
const cold = $('Going cold').first().json.results || [];
const days = (d) => d ? Math.floor((Date.now() - new Date(d)) / 864e5) : '?';
const text = ['Call first today:',
  ...(call.length ? call.map((c, i) => `${i + 1}. ${c.properties.company || c.properties.firstname} · ${c.properties.harvest_score}`) : ['(nobody new)']),
  '', 'Going cold (no activity 7+ days):',
  ...(cold.length ? cold.map(d => `- ${d.properties.dealname} · ${days(d.properties.notes_last_updated)} days`) : ['(none)'])].join('\n');
return [{ json: { text } }];

const DAY = 864e5, now = Date.now();
const stages = Object.fromEntries(($('Pipeline stages').first().json.results || []).flatMap(p => p.stages)
  .map(s => [s.id, { label: s.label, p: Number(s.metadata?.probability || 0) }]));
const deals = $('Deals').first().json.results || [];
const dealContact = Object.fromEntries(($('Deal contacts').first().json.results || []).map(r => [String(r.from.id), String(r.to[0]?.toObjectId || '')]));
const source = Object.fromEntries(($json.results || []).map(c => [String(c.id), c.properties.lead_source || 'unknown']));
const val = (d) => Number(d.properties.weekly_value_ngn || 0);
const ngn = (n) => '₦' + Math.round(n).toLocaleString('en-NG');
const open = deals.filter(d => d.properties.hs_is_closed !== 'true');
const newDeals = deals.filter(d => now - new Date(d.properties.createdate) < 7 * DAY);
const bySource = {}; for (const d of newDeals) { const s = source[dealContact[d.id]] || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
const byStage = {}; for (const d of open) { const s = stages[d.properties.dealstage]?.label || d.properties.dealstage; byStage[s] = (byStage[s] || 0) + val(d); }
const weighted = open.reduce((a, d) => a + val(d) * (stages[d.properties.dealstage]?.p || 0), 0);
const month = deals.filter(d => d.properties.hs_is_closed === 'true');
const won = month.filter(d => d.properties.hs_is_closed_won === 'true');
const lost = month.filter(d => d.properties.hs_is_closed_won !== 'true');
const entered = (d) => new Date(d.properties.hs_v2_date_entered_current_stage || d.properties.hs_lastmodifieddate).getTime();
const stuck = open.filter(d => now - entered(d) > 14 * DAY).sort((a, b) => entered(a) - entered(b)).slice(0, 3);
const summary = [
  'Harvest Lane pipeline · Monday',
  `New deals by source (7 days): ${Object.entries(bySource).map(([k, v]) => `${k} ${v}`).join(' · ') || 'none'}`,
  `Open value by stage: ${Object.entries(byStage).map(([k, v]) => `${k} ${ngn(v)}`).join(' · ') || 'none'}`,
  `Won this month: ${won.length} (${won.map(d => d.properties.dealname).join(', ') || '-'})`,
  `Lost this month: ${lost.length} (${lost.map(d => `${d.properties.dealname}: ${d.properties.lost_reason || 'no reason!'}`).join('; ') || '-'})`,
  `Weighted forecast (weekly): ${ngn(weighted)}`,
].join('\n');
return stuck.length
  ? stuck.map(d => ({ json: { summary, deal_id: d.id, dealname: d.properties.dealname, days: Math.floor((now - entered(d)) / DAY), stage: stages[d.properties.dealstage]?.label || '' } }))
  : [{ json: { summary, deal_id: '', dealname: '', days: 0, stage: '' } }];

