const details = parse(p.details, {});
let error = '';
if (!ALLOWED.includes(p.action)) error = `"${p.action}" is not on the allowed list (${ALLOWED.join(', ')}). Deleting, changing stages, messaging customers and changing permissions can never be proposed.`;
else if (!p.evidence) error = 'Every proposal needs evidence.';
return { valid: !error, error, action: p.action, target_ids, details, evidence: p.evidence || '', expected_effect: p.expected_effect || '',
  reversible: p.reversible === true || String(p.reversible) === 'true' };

