parameters.jsCode:
const ALLOW = ['merge_companies', 'bulk_update_property', 'create_task', 'require_field', 'score_weight'];
const NEVER_FIELDS = ['dealstage', 'pipeline', 'hubspot_owner_id', 'marketing_consent', 'consent_date', 'hs_email_optout', 'lifecyclestage'];
const p = $json;
const d = p.details || {};
let reason = '';
if (!ALLOW.includes(p.action)) reason = `action ${p.action} is not on the allow-list`;
if (p.action === 'bulk_update_property' && NEVER_FIELDS.includes(String(d.property).trim().toLowerCase())) reason = `property ${d.property} can't be changed by the executor`;
// object_type goes into the URL: only these three, so nothing else (archive, merge, associations) can be reached.
if (p.action === 'bulk_update_property' && !['contacts', 'companies', 'deals'].includes(String(d.object_type))) reason = `object type ${d.object_type} is not allowed`;
if (p.action === 'merge_companies' && (!d.primary_id || !d.merge_id)) reason = 'merge needs primary_id and merge_id';
if (!reason && p.action === 'bulk_update_property' && !(Array.isArray(p.target_ids) && p.target_ids.length && d.object_type && d.property)) reason = 'bulk update needs target_ids, object_type and property';
return { ...p, details: d, allowed: !reason, reason };

// 1. Signature: HMAC-SHA512 of the raw body with your secret key must equal x-paystack-signature.
const crypto = require('crypto');
const secret = $env.PAYSTACK_SECRET_KEY;          // TEST secret key, kept in ONE place: the n8n environment
const item = $input.first();
const headers = item.json.headers || {};
const sig = String(headers['x-paystack-signature'] || '');
let raw = '';
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
}
let valid = false;
if (secret && raw && sig) {
  const hash = crypto.createHmac('sha512', secret).update(raw).digest('hex');
  valid = hash.length === sig.length && crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(sig));
}
let body = item.json.body;
if ((!body || typeof body !== 'object') && raw) { try { body = JSON.parse(raw); } catch (e) { body = {}; } }
body = body || {};
return [{ json: {
  signature_valid: valid,
  reason: !secret ? 'PAYSTACK_SECRET_KEY not set' : !raw ? 'raw body missing' : !sig ? 'no signature header' : valid ? 'ok' : 'signature mismatch',
  event: body.event || '',
  reference: (body.data && body.data.reference) || '',
  body
} }];

// 2. Only Paystack's own answer counts. Amounts are in kobo.
const TIERS = {
  starter: { deposit: 225000, monthly: 30000 },
  growth:  { deposit: 425000, monthly: 60000 },
  partner: { deposit: 600000, monthly: 120000 }
};
const v = $input.first().json.data || {};
const hook = $('Verify signature').first().json.body.data || {};
const meta = v.metadata || hook.metadata || {};
const fields = Array.isArray(meta.custom_fields) ? meta.custom_fields : [];
const field = (name) => (fields.find(f => (f.display_name || f.variable_name || '').toLowerCase() === name) || {}).value;
const tierKey = String(meta.tier || field('tier') || '').toLowerCase().split(/[\s:]/)[0];
const isRenewal = !!(v.plan && (v.plan.plan_code || typeof v.plan === 'string'));
const tier = TIERS[tierKey];
const expectedNgn = tier ? (isRenewal ? tier.monthly : tier.deposit) : null;
const ok = v.status === 'success' && tier !== undefined && v.amount === expectedNgn * 100 && v.currency === 'NGN';
return [{ json: {
  verified: ok,
  why: v.status !== 'success' ? 'Paystack status is ' + (v.status || 'unknown') : !tier ? 'tier missing in metadata' : ok ? 'ok' : 'amount ' + v.amount + ' kobo, expected ' + (expectedNgn * 100),
  reference: v.reference || $('Verify signature').first().json.reference,
  kind: isRenewal ? 'monthly' : 'deposit',
  tier: tierKey ? tierKey[0].toUpperCase() + tierKey.slice(1) : '',
  amount_ngn: (v.amount || 0) / 100,
  business: field('business name') || meta.business_name || '',
  contact: [v.customer && v.customer.first_name, v.customer && v.customer.last_name].filter(Boolean).join(' '),
  email: (v.customer && v.customer.email || '').toLowerCase(),
  paid_at: v.paid_at || new Date().toISOString()
} }];

