const crypto = require('crypto');
const secret = $env.PAYSTACK_SECRET_KEY;
const item = $input.first();
const sig = String((item.json.headers || {})['x-paystack-signature'] || '');
let raw = '';
if (item.binary && item.binary.data) raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
let valid = false;
if (secret && raw && sig) {
  const hash = crypto.createHmac('sha512', secret).update(raw).digest('hex');
  valid = hash.length === sig.length && crypto.timingSafeEqual(Buffer.from(hash), Buffer.from(sig));
}
let body = item.json.body;
if ((!body || typeof body !== 'object') && raw) { try { body = JSON.parse(raw); } catch (e) { body = {}; } }
body = body || {};
return [{ json: { signature_valid: valid, event: body.event || '', reference: body.data?.reference || '', order_id: body.data?.metadata?.order_id || null } }];

const v = $('Verify transaction').first().json.data || {};
const o = $input.first().json;
