// Who, what, what's been tried; reply time by the hour; storm grouping (curveball 3).
const t = $('When Executed by Another Workflow').first().json;
const now = $now.setZone('Africa/Lagos');
const working = now.weekday <= 6 && now.hour >= 8 && now.hour < 18;
const when = working ? 'within 30 minutes' : (now.hour < 8 ? 'by 9 a.m. today' : 'by 9 a.m. tomorrow');
const issue = String(t.issue_key || 'other').toLowerCase().trim();
const since = now.minus({ minutes: 30 }).toISO();
// Hand-overs for the same issue in the last 30 minutes, including this one.
const recent = $('Recent hand-overs').all().map(i => i.json)
  .filter(r => r.issue_key === issue && Date.parse(String(r.at)) >= Date.parse(since) && r.session !== `tg-${t.chat_id}`).length + 1;
const mode = recent <= 5 ? 'individual' : recent === 6 ? 'group_summary' : 'grouped_silent';
const summary = `🙋 Hand-over · ${t.customer_name || 'Customer'} (tg-${t.chat_id}) · ${now.toFormat('HH:mm')}\n` +
  `Wants: ${t.wants}\nTried: ${t.tried}\nSuggested: ${t.suggested || 'reply ' + when}`;
const group = `🌧 ${recent} customers in 30 min, all "${issue}". Individual alerts paused for this issue. ` +
  `Open the Handovers sheet, then approve one honest status message for them all.`;
return [{ json: { session: `tg-${t.chat_id}`, issue_key: issue, summary, group, mode, when,
  is_eval: String(t.is_eval) === 'true',
  customer_message: `I've passed this to Tolu with all the details. She'll reply ${when}.` } }];

// Sanitise before memory or the model ever sees it: mask card-like numbers and codes.
let text = String($json.text ?? '');
const before = text;
text = text.replace(/\b(?:\d[ -]?){12,19}\b/g, '[card number removed]');
text = text.replace(/\b(pin|otp|cvv|password)\b\s*[:=]?\s*\S+/gi, '$1 [removed]');
return { json: { ...$json, text, masked: text !== before } };

