const crypto = require('crypto');
const item = $input.first();
const sig = String((item.json.headers || {})['x-hub-signature-256'] || '');
let raw = '';
if (item.binary && item.binary.data) raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const secret = $env.META_APP_SECRET;
let valid = false;
if (secret && raw && sig.startsWith('sha256=')) {
  const h = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  valid = h.length === sig.length && crypto.timingSafeEqual(Buffer.from(h), Buffer.from(sig));
}
if (!valid) return [{ json: { valid: false } }];
const body = item.json.body || JSON.parse(raw);
const platform = body.object === 'instagram' ? 'instagram' : 'facebook';
const out = [];
for (const e of (body.entry || [])) {
  for (const ch of (e.changes || [])) {
    const v = ch.value || {};
    if (ch.field === 'feed' && v.item === 'comment' && v.verb === 'add' && v.from?.id !== e.id)
      out.push({ platform: 'facebook', kind: 'comment', item_id: v.comment_id, thread_id: v.post_id, author_id: v.from?.id, author_name: v.from?.name || '', text: v.message || '', received_at: new Date((v.created_time || Date.now() / 1000) * 1000).toISOString(), link: v.post?.permalink_url || '' });
    if (ch.field === 'comments' && v.from?.id !== e.id)
      out.push({ platform: 'instagram', kind: 'comment', item_id: v.id, thread_id: v.media?.id, author_id: v.from?.id, author_name: v.from?.username || '', text: v.text || '', received_at: new Date().toISOString(), link: '' });
  }
  for (const m of (e.messaging || [])) {
    if (!m.message || m.message.is_echo) continue;
    out.push({ platform, kind: 'dm', item_id: m.message.mid, thread_id: m.sender.id, author_id: m.sender.id, author_name: '', text: m.message.text || '', received_at: new Date(m.timestamp).toISOString(), link: '' });
  }
}
return out.length ? out.map(json => ({ json: { valid: true, ...json } })) : [{ json: { valid: true, empty: true } }];

