// Card 4. Stage IDs: replace with yours.
const STAGE = { tasting: 'YOUR_STAGE_TASTING_BOOKED', proposal: 'YOUR_STAGE_PROPOSAL_SENT', won: 'closedwon', lost: 'closedlost' };
const d = $('One per deal').item.json;
const p = d.properties;
const at = (days, hour = 9) => { const t = new Date(); t.setDate(t.getDate() + days); t.setHours(hour, 0, 0, 0); return t.toISOString(); };
let task = null, won = false;
if (p.dealstage === STAGE.tasting) {
  const day = p.next_step_date ? new Date(p.next_step_date) : null;
  if (day) day.setDate(day.getDate() - 1);
  task = { subject: 'Prepare tasting crate and confirm: ' + p.dealname, due: day ? day.toISOString() : at(1) };
} else if (p.dealstage === STAGE.proposal) {
  task = { subject: 'Follow up on proposal: ' + p.dealname, due: at(3) };
} else if (p.dealstage === STAGE.won) {
  task = { subject: 'Start onboarding (6.2) and welcome series: ' + p.dealname, due: at(0, 17) }; won = true;
} else if (p.dealstage === STAGE.lost) {
  if (!p.lost_reason) task = { subject: 'Add a lost reason: ' + p.dealname, due: at(0, 17) };
  else if (/current supplier/i.test(p.lost_reason)) task = { subject: 'Check in again (lost to current supplier): ' + p.dealname, due: at(182) };
}
return { json: { deal_id: d.id, stage: p.dealstage, owner: p.hubspot_owner_id || 'YOUR_HUBSPOT_OWNER_ID', task, won } };

