// Code, not the agent, decides what may even be shown to Tolu.
const ALLOWED = ['merge_companies', 'bulk_update_property', 'create_task', 'require_field', 'score_weight'];
const FORBIDDEN = /delete|dealstage|stage|message|whatsapp|email blast|permission|consent/i;
return $input.all().filter(i => i.json.id).map(i => {
  const p = i.json;
  const det = JSON.stringify(p.details || {});
  let ok = ALLOWED.includes(p.action) && !(p.action === 'bulk_update_property' && FORBIDDEN.test(det));
  if (p.action === 'merge_companies' && !(p.details && p.details.domain)) ok = false;   // merges need a shared verified domain
  return { json: { ...p, allowed: ok } };
});

