parameters.jsCode:
const ALLOWED = ['merge_companies', 'bulk_update_property', 'create_task', 'require_field', 'score_weight'];
const p = $json;
const ids = (Array.isArray(p.target_ids) ? p.target_ids : []).map(String);
const objects = ['companies', 'contacts', 'deals'];
const forbiddenProp = /^(dealstage|hs_|lifecyclestage|marketing_consent|hubspot_owner_id)/;
let ok = ALLOWED.includes(p.action);
if (p.action === 'merge_companies') ok = ok && ids.length === 2 && !!p.details?.domain;
if (p.action === 'bulk_update_property') ok = ok && objects.includes(p.details?.object) && !!p.details?.property && !forbiddenProp.test(p.details.property) && ids.length > 0 && ids.length <= 100;
return { json: { ...p, ids, ok } };

const p = $('Allow-list check again').item.json;
const rows = $json.results || [];
const norm = d => String(d || '').toLowerCase().replace(/^www\./, '');
const ok = rows.length === 2 && norm(rows[0].properties.domain) && norm(rows[0].properties.domain) === norm(rows[1].properties.domain) && norm(rows[0].properties.domain) === norm(p.details.domain);
return { json: { id: p.id, ok, before: rows.map(r => ({ id: r.id, ...r.properties })), keep: p.ids[0], merge: p.ids[1] } };
